import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0008: 为什么高风险动作前必须持久化关键状态","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0008-why-persist-before-high-risk-actions.md","filePath":"zh/adr/ADR-0008-why-persist-before-high-risk-actions.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0008-why-persist-before-high-risk-actions.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0008-为什么高风险动作前必须持久化关键状态" tabindex="-1">ADR-0008: 为什么高风险动作前必须持久化关键状态 <a class="header-anchor" href="#adr-0008-为什么高风险动作前必须持久化关键状态" aria-label="Permalink to “ADR-0008: 为什么高风险动作前必须持久化关键状态”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：docs/guide/persistence.md §7.3，recovery-engine.md §6.6</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>引擎在执行恢复动作期间崩溃是必然场景（断电、OOM、升级）。若动作已发生但 记录没落盘，重启后核心不知道动作执行过——重试意味着第二次重启服务/第二次 下发网络变更，副作用翻倍且不可审计。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p>写序保证：attempt 先以 <code>outcome = NULL</code>（Executing 态）持久化，<strong>然后</strong>才执行 外部动作；执行完成回写 outcome。崩溃恢复时：NULL outcome 语义为&quot;结果可能未知&quot;， 绝不当作&quot;未执行&quot;而盲目重试，也不当作&quot;成功&quot;——重诊断（ADR-0013）。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>执行后补写</strong>：执行与写库之间的崩溃窗口丢失事实，重试副作用翻倍。</li><li><strong>全部写内存、定期刷盘</strong>：窗口更大；审计不完整。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：任意时刻崩溃后系统状态可推导；审计链完整（谁在何时执行了什么）。 缺点：每次动作多一次同步写（SQLite WAL 下代价小）；代码路径要严格保持写序。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li><code>resume_unfinished</code> 把未终态运行标记 OutcomeUnknown 并停止自动重试。</li><li>高风险动作（RiskLevel::High）额外走预算与授权（ADR-0012），持久化是前提。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};